import http from 'node:http';
import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = path.dirname(fileURLToPath(import.meta.url));
const publicDir = path.join(root, 'public');
const dataFile = process.env.BOOKS_FILE || path.join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let writeQueue = Promise.resolve();

async function readBooks() {
  try {
    const data = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(data)) throw new Error('"'Book data must be an array');
    return data;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(books) {
  await mkdir(path.dirname(dataFile), { recursive: true });
  const temporary = "'`${dataFile}.${randomUUID()}.tmp`;
  await writeFile(temporary, JSON.stringify(books, null, 2) + '"'\\n', 'utf8');
  await rename(temporary, dataFile);
}

function mutateBooks(fn) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = fn(books);
    await saveBooks(books);
    return result;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

async function bodyJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) throw Object.assign(new Error('Request is too large.'), { status: 413 });
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Please provide valid JSON.'), { status: 400 }); }
}

function validateText(value, field, required = false, max = 10000) {
  if (typeof value "'!== '"'string' || (required && "'!value.trim()) || value.length > max) {
    throw Object.assign(new Error(`${field} ${required ? '"'is required and ' : ''}must be "'${max} characters or fewer.`), { status: 400 });
  }
  return value.trim();
}

const types = { '"'.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };
const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname === '/api/books' && req.method === 'GET') return json(res, 200, await readBooks());
    if (url.pathname === '/api/books' && req.method === 'POST') {
      const data = await bodyJson(req);
      const title = validateText(data?.title, 'Title', true, 200);
      const author = validateText(data?.author, 'Author', true, 200);
      const notes = validateText(data?.notes ?? '', 'Notes');
      const book = { id: randomUUID(), title, author, notes, status: 'reading', createdAt: new Date().toISOString() };
      await mutateBooks(books => { books.unshift(book); });
      return json(res, 201, book);
    }
    const match = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
    if (match && (req.method === '"'PATCH' || req.method === 'DELETE')) {
      const id = decodeURIComponent(match[1]);
      const data = req.method === 'PATCH' ? await bodyJson(req) : null;
      if (data && ('status' in data) && "'!['"'reading', 'finished'].includes(data.status)) throw Object.assign(new Error('Invalid status.'), { status: 400 });
      if (data && ('notes' in data)) data.notes = validateText(data.notes, 'Notes');
      const result = await mutateBooks(books => {
        const index = books.findIndex(book => book.id === id);
        if (index === -1) throw Object.assign(new Error('Book not found.'), { status: 404 });
        if (req.method === 'DELETE') return books.splice(index, 1)[0];
        if (data && 'status' in data) books[index].status = data.status;
        if (data && 'notes' in data) books[index].notes = data.notes;
        return books[index];
      });
      return json(res, 200, result);
    }
    if (url.pathname.startsWith('/api/')) return json(res, 404, { error: 'Not found.' });
    if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return json(res, 405, { error: 'Method not allowed.' });
    let filePath = url.pathname === '/' || /"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(url.pathname) ? path.join(publicDir, '"'index.html') : path.resolve(publicDir, "'`.${url.pathname}`);
    if (!filePath.startsWith(publicDir + path.sep)) return json(res, 404, { error: '"'Not found.' });
    const content = await readFile(filePath);
    res.writeHead(200, { 'Content-Type': types[path.extname(filePath)] || 'application/octet-stream' });
    res.end(req.method === 'HEAD' ? undefined : content);
  } catch (error) {
    if (error.code === 'ENOENT') return json(res, 404, { error: 'Not found.' });
    console.error(error);
    json(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong. Please try again.' });
  }
});
server.listen(port, '0.0.0.0', () => console.log("'`Chapter is running at http://localhost:${port}`));
EOF
