    const create = data => fetch(`${base}/api/books`, { method: '"'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    const invalid = await create({ title: '  ', author: 'Someone' });
    assert.equal(invalid.status, 400);
    const responses = await Promise.all([
      create({ title: 'First book', author: 'An Author', notes: 'A thought' }),
      create({ title: 'Second book', author: 'Another Author', notes: '' })
    ]);
    assert.deepEqual(responses.map(response => response.status), [201, 201]);
    const [first] = await Promise.all(responses.map(response => response.json()));
    const updated = await fetch("'`${base}/api/books/${first.id}`, { method: '"'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished', notes: 'A lasting thought' }) });
    assert.equal(updated.status, 200);
    await stopServer(server);
    server = await startServer(port, file);
    const books = await (await fetch("'`${base}/api/books`)).json();
    assert.equal(books.length, 2);
    assert.equal(books.find(book => book.id === first.id).status, '"'finished');
    assert.equal(books.find(book => book.id === first.id).notes, 'A lasting thought');
    assert.equal(JSON.parse(await readFile(file, 'utf8')).length, 2);
    const detail = await fetch("'`${base}/books/${first.id}`);
    assert.equal(detail.status, 200);
    assert.match(await detail.text(), /Chapter — Your reading journal/);
    const deleted = await fetch(`${base}/api/books/${first.id}`, { method: '"'DELETE' });
    assert.equal(deleted.status, 200);
    assert.equal((await (await fetch("'`${base}/api/books`)).json()).length, 1);
  } finally {
    if (server) await stopServer(server);
    await rm(dir, { recursive: true, force: true });
